import React, { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { useGLTF, useAnimations, OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

const MaleAvatar = ({ avatarMode, onIntroComplete }) => {
  const group = useRef();
  const { scene, animations: modelAnimations } = useGLTF('/avatars/omkar.glb');
  const { actions, mixer } = useAnimations(modelAnimations, group);

  // ✅ Load ALL male animations
  const standingIdle1 = useGLTF('/animations/male/M_Standing_Idle_001.glb');
  const standingIdle2 = useGLTF('/animations/male/M_Standing_Idle_002.glb');
  const standingVar1 = useGLTF('/animations/male/M_Standing_Idle_Variations_001.glb');
  const standingVar2 = useGLTF('/animations/male/M_Standing_Idle_Variations_002.glb');
  const standingVar3 = useGLTF('/animations/male/M_Standing_Idle_Variations_003.glb');
  const standingVar4 = useGLTF('/animations/male/M_Standing_Idle_Variations_004.glb');
  const standingVar5 = useGLTF('/animations/male/M_Standing_Idle_Variations_005.glb');

  const talk1 = useGLTF('/animations/male/M_Talking_Variations_001.glb');
  const talk2 = useGLTF('/animations/male/M_Talking_Variations_002.glb');
  const talk3 = useGLTF('/animations/male/M_Talking_Variations_003.glb');
  const talk4 = useGLTF('/animations/male/M_Talking_Variations_004.glb');
  const talk5 = useGLTF('/animations/male/M_Talking_Variations_005.glb');
  const talk6 = useGLTF('/animations/male/M_Talking_Variations_006.glb');

  const walk1 = useGLTF('/animations/male/M_Walk_001.glb');
  const walk2 = useGLTF('/animations/male/M_Walk_002.glb');
  const dance1 = useGLTF('/animations/male/M_Dances_001.glb');
  const jump1 = useGLTF('/animations/male/M_Jog_Jump_001.glb');

  const [currentAction, setCurrentAction] = useState(null);

  // Animation mapping
  const animationsData = {
    // ✅ IDLE (when NOT speaking)
    idle: [
      { clips: standingIdle1.animations, speed: 0.4 },
      { clips: standingIdle2.animations, speed: 0.4 },
      { clips: standingVar1.animations, speed: 0.4 },
      { clips: standingVar2.animations, speed: 0.4 },
      { clips: standingVar3.animations, speed: 0.4 },
      { clips: standingVar4.animations, speed: 0.4 },
      { clips: standingVar5.animations, speed: 0.4 },
    ],
    // ✅ TALK (when speaking)
    talk: [
      { clips: talk1.animations, speed: 0.5 },
      { clips: talk2.animations, speed: 0.5 },
      { clips: talk3.animations, speed: 0.5 },
      { clips: talk4.animations, speed: 0.5 },
      { clips: talk5.animations, speed: 0.5 },
      { clips: talk6.animations, speed: 0.5 },
    ],
    walk: [{ clips: walk1.animations, speed: 0.4 }, { clips: walk2.animations, speed: 0.4 }],
    dance: [{ clips: dance1.animations, speed: 0.3 }],
    jump: [{ clips: jump1.animations, speed: 0.5 }],
  };

  useEffect(() => {
    if (mixer && scene) {
      let animArray = [];
      
      if (avatarMode === 'talk') {
        animArray = animationsData.talk;
      } else if (avatarMode === 'walk') {
        animArray = animationsData.walk;
      } else if (avatarMode === 'dance') {
        animArray = animationsData.dance;
      } else if (avatarMode === 'jump') {
        animArray = animationsData.jump;
      } else {
        // Default to idle
        animArray = animationsData.idle;
      }

      // Pick random animation from array
      const randomAnim = animArray[Math.floor(Math.random() * animArray.length)];

      if (randomAnim && randomAnim.clips && randomAnim.clips.length > 0) {
        const clip = randomAnim.clips[0];
        const action = mixer.clipAction(clip);
        
        if (currentAction && currentAction !== action) {
          currentAction.fadeOut(0.3);
        }

        action.reset();
        action.fadeIn(0.3);
        action.timeScale = randomAnim.speed;
        action.play();
        setCurrentAction(action);
      }
    }
  }, [avatarMode, mixer, scene]);

  useEffect(() => {
    if (onIntroComplete) {
      onIntroComplete({
        message: "Hello! I'm Omkar, your AI tutor. How can I help you today?"
      });
    }
  }, [onIntroComplete]);

  return <primitive ref={group} object={scene} scale={2} position={[0, -2, 0]} />;
};

const FemaleAvatar = ({ avatarMode, onIntroComplete }) => {
  const group = useRef();
  const { scene, animations: modelAnimations } = useGLTF('/avatars/priya.glb');
  const { actions, mixer } = useAnimations(modelAnimations, group);

  // ✅ Load ALL female animations
  const standingIdle1 = useGLTF('/animations/female/F_Standing_Idle_001.glb');
  const standingVar1 = useGLTF('/animations/female/F_Standing_Idle_Variations_001.glb');
  const standingVar2 = useGLTF('/animations/female/F_Standing_Idle_Variations_002.glb');
  const standingVar3 = useGLTF('/animations/female/F_Standing_Idle_Variations_003.glb');
  const standingVar4 = useGLTF('/animations/female/F_Standing_Idle_Variations_004.glb');
  const standingVar5 = useGLTF('/animations/female/F_Standing_Idle_Variations_005.glb');

  const talk1 = useGLTF('/animations/female/F_Talking_Variations_001.glb');
  const talk2 = useGLTF('/animations/female/F_Talking_Variations_002.glb');
  const talk3 = useGLTF('/animations/female/F_Talking_Variations_003.glb');
  const talk4 = useGLTF('/animations/female/F_Talking_Variations_004.glb');
  const talk5 = useGLTF('/animations/female/F_Talking_Variations_005.glb');
  const talk6 = useGLTF('/animations/female/F_Talking_Variations_006.glb');

  const walk1 = useGLTF('/animations/female/F_Walk_002.glb');
  const walk2 = useGLTF('/animations/female/F_Walk_003.glb');
  const dance1 = useGLTF('/animations/female/F_Dances_001.glb');
  const jog1 = useGLTF('/animations/female/F_Jog_001.glb');

  const [currentAction, setCurrentAction] = useState(null);

  const animationsData = {
    // ✅ IDLE (when NOT speaking)
    idle: [
      { clips: standingIdle1.animations, speed: 0.4 },
      { clips: standingVar1.animations, speed: 0.4 },
      { clips: standingVar2.animations, speed: 0.4 },
      { clips: standingVar3.animations, speed: 0.4 },
      { clips: standingVar4.animations, speed: 0.4 },
      { clips: standingVar5.animations, speed: 0.4 },
    ],
    // ✅ TALK (when speaking)
    talk: [
      { clips: talk1.animations, speed: 0.5 },
      { clips: talk2.animations, speed: 0.5 },
      { clips: talk3.animations, speed: 0.5 },
      { clips: talk4.animations, speed: 0.5 },
      { clips: talk5.animations, speed: 0.5 },
      { clips: talk6.animations, speed: 0.5 },
    ],
    walk: [{ clips: walk1.animations, speed: 0.4 }, { clips: walk2.animations, speed: 0.4 }],
    dance: [{ clips: dance1.animations, speed: 0.3 }],
    jump: [{ clips: jog1.animations, speed: 0.5 }],
  };

  useEffect(() => {
    if (mixer && scene) {
      let animArray = [];
      
      if (avatarMode === 'talk') {
        animArray = animationsData.talk;
      } else if (avatarMode === 'walk') {
        animArray = animationsData.walk;
      } else if (avatarMode === 'dance') {
        animArray = animationsData.dance;
      } else if (avatarMode === 'jump') {
        animArray = animationsData.jump;
      } else {
        // Default to idle
        animArray = animationsData.idle;
      }

      const randomAnim = animArray[Math.floor(Math.random() * animArray.length)];

      if (randomAnim && randomAnim.clips && randomAnim.clips.length > 0) {
        const clip = randomAnim.clips[0];
        const action = mixer.clipAction(clip);
        
        if (currentAction && currentAction !== action) {
          currentAction.fadeOut(0.3);
        }

        action.reset();
        action.fadeIn(0.3);
        action.timeScale = randomAnim.speed;
        action.play();
        setCurrentAction(action);
      }
    }
  }, [avatarMode, mixer, scene]);

  useEffect(() => {
    if (onIntroComplete) {
      onIntroComplete({
        message: "Hi! I'm Priya, your AI tutor. What would you like to learn today?"
      });
    }
  }, [onIntroComplete]);

  return <primitive ref={group} object={scene} scale={2} position={[0, -2, 0]} />;
};

export const Avatar3D = ({ avatarMode, companionId, onIntroComplete }) => {
  const isMale = companionId === 'omkar_ai';

  return (
    <Canvas
      camera={{ position: [0, 0, 5], fov: 50 }}
      style={{ width: '100%', height: '100%' }}
      gl={{ antialias: true }}
    >
      <ambientLight intensity={0.8} />
      <directionalLight position={[5, 5, 5]} intensity={1} />
      <directionalLight position={[-5, 5, -5]} intensity={0.5} />
      
      {isMale ? (
        <MaleAvatar avatarMode={avatarMode} onIntroComplete={onIntroComplete} />
      ) : (
        <FemaleAvatar avatarMode={avatarMode} onIntroComplete={onIntroComplete} />
      )}
      
      <OrbitControls
        enablePan={false}
        enableZoom={false}
        minPolarAngle={Math.PI / 3}
        maxPolarAngle={Math.PI / 2}
      />
    </Canvas>
  );
};

useGLTF.preload('/avatars/omkar.glb');
useGLTF.preload('/avatars/priya.glb');
